IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Premium_GrossUpRate') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) 
begin
DROP Function Premium_GrossUpRate
end
GO
CREATE Function Premium_GrossUpRate(@P_ANO as int,@P_Code as varchar(10),@P_Period Int)            
RETURNS Float            
AS            
BEGIN            
 Declare @Fee Float  
 Declare @Commission Float    
 Declare @DetailF bit           
                        
 Select Top 1 @DetailF=1 from AAccBS Where ANO=@P_ANO                    
 if @DetailF is null     
 Select @DetailF=0            
     
  
 Select @Commission=1  
 if @DetailF=1    
 Begin     
  DECLARE Fee_CURSOR Cursor FOR      
  Select sum(coalesce(AAccBSDet.Fee,AAccBS.Fee))
  From AAccBS Left Join AAccBSDet on ((AAccBSDet.Period=0 or AAccBSDet.Period=@P_Period) and AAccBSDet.ID=AAccBS.ID and AAccBSDet.BSType=AAccBS.BSType and AAccBSDet.ANO=AAccBS.ANO and AAccBSDet.Code=@P_Code)  
  Where AAccBS.ANO=@P_ANO  
  Group By AAccBS.GrossUpF
 end     
 else   
 Begin     
  DECLARE Fee_CURSOR Cursor FOR  
  Select sum(coalesce(AccBSDet.Fee,AccBS.Fee))
  From AccBS Left Join AccBSDet on ((AccBSDet.Period=0 or AccBSDet.Period=@P_Period) and AccBSDet.ID=AccBS.ID and AccBSDet.BSType=AccBS.BSType and AccBSDet.ANO=AccBS.ANO and AccBSDet.Code=@P_Code and AccBSDet.InceptionF=0)  
  Where AccBS.ANO=@P_ANO  
  Group By AccBS.GrossUpF
 end    
   
 OPEN Fee_Cursor  
 FETCH FROM Fee_Cursor into @Fee  
 WHILE @@FETCH_STATUS = 0      
 BEGIN      
    Select @Commission=@Commission*100/(100-@Fee)  
    FETCH NEXT FROM Fee_Cursor into @Fee  
 End      
 Close Fee_Cursor  
 Deallocate Fee_Cursor  
                     
 return(@Commission)            
End            

GO

