IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QRCESSIONDET') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
DROP Procedure QRCESSIONDET 
