IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'SysUserArea') AND type in (N'U'))
begin

CREATE TABLE SysUserArea(
	[ID] [varchar](50) NOT NULL,
	[Area] [varchar](10) NOT NULL
) ON [PRIMARY]



SET ANSI_PADDING OFF


ALTER TABLE SysUserArea  WITH NOCHECK ADD  CONSTRAINT [FK_SysUserArea_SysUser] FOREIGN KEY([ID])
