if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'FN_UserProfile') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN
DROP FUNCTION FN_UserProfile 
END
GO
CREATE FUNCTION FN_UserProfile (@P_UserID as varchar(50))            
RETURNS TABLE            
as RETURN(            
SELECT Profile.*       
 from Profile       
 Inner join SysUser on (SysUser.ID=@P_UserID)      
 Where (
 SysUser.Type='SUPERVISOR' or 
 Profile.Area='' or
 Exists (
	 Select Top 1 SysUserArea.Area 
	 from SysUserArea 
	 Where SysUserArea.ID=@P_UserID 
	 and SysUserArea.Area=Profile.Area
 )
 or
 not exists (
	 Select Top 1 SysUserArea.Area 
	 from SysUserArea 
	 Where SysUserArea.ID=@P_UserID 
 )
 )
)
