SELECT DISTINCT TOI.TOI, TOI.DESCRIPTION, ICOVER.INO
FROM ACCEPTANCE, COVER, ICALC, ICOVER, COL, TOI
WHERE ACCEPTANCE.ANO=@P_ANO
AND COVER.CNO=ACCEPTANCE.CNO
AND COL.COL=@P_COL AND COL.AllowedF=1
