CREATE Procedure Get_VAccount_info(@P_VID int, @P_AccountNo varchar(150))
As
 Declare @Bank varchar(10)
 Declare @CollNo varchar(20)
 Declare @P_PDate smalldatetime
 Select @P_PDate=convert(varchar(10), getdate(),1)
 Select @Bank=V1.Bank,  @CollNo=V2.CollNo from VAccount V1, VAccountD V2 Where V2.VID=V1.VID and V1.VID=@P_VID and V2.AccountNo=@P_Accountno

 if @CollNo<>''
	 Select top 1 C1.Last_Opr as UserID, @Bank as Bank, @P_AccountNo as AccountNo, '' as A_PolicyNo, @CollNo as CollNo, Profile.Name, 
	 @P_PDate as PDate,
	 C1.CollDate as NextDueDate, C3.TAmount as Nominal, 'For the Period of ' + convert(varchar(20), C1.Sdate, 6) + ' - ' + convert(varchar(20), C1.Edate, 6) as Description
	 from CollectionH C1, CollectionV C2, CollAmount C3, nVoucher V, ProAcc, Profile
	 Where C1.Collno=@CollNo and C3.CollNo=C1.CollNo and C2.CollNo=C1.CollNo and V.Voucher=C2.Voucher and ProAcc.ProAcc=V.ProAcc and Profile.ID=ProAcc.ID
else
	 
	 Select Max(A.LUserID) as UserID, @Bank as Bank, @P_AccountNo as AccountNo, A.A_PolicyNo, '' as CollNo, Profile.Name, 
	 @P_PDate as PDate,
	 Max(
	 Case 
		When A.Installment=0 Then A.BillDate
		When A.Installment>=1 and @P_PDate<=A.DueDate_1 Then A.DueDate_1
		When A.Installment>=2 and @P_PDate<=A.DueDate_2 Then A.DueDate_2
		When A.Installment>=3 and @P_PDate<=A.DueDate_3 Then A.DueDate_3
		When A.Installment>=4 and @P_PDate<=A.DueDate_4 Then A.DueDate_4
		When A.Installment>=5 and @P_PDate<=A.DueDate_5 Then A.DueDate_5
		When A.Installment>=6 and @P_PDate<=A.DueDate_6 Then A.DueDate_6
		When A.Installment>=7 and @P_PDate<=A.DueDate_7 Then A.DueDate_7
		When A.Installment>=8 and @P_PDate<=A.DueDate_8 Then A.DueDate_8
		When A.Installment>=9 and @P_PDate<=A.DueDate_9 Then A.DueDate_9
		When A.Installment>=10 and @P_PDate<=A.DueDate_10 Then A.DueDate_10
		When A.Installment>=11 and @P_PDate<=A.DueDate_11 Then A.DueDate_11
		When A.Installment>=12 and @P_PDate<=A.DueDate_12 Then A.DueDate_12
		When A.Installment>=13 and @P_PDate<=A.DueDate_13 Then A.DueDate_13
		When A.Installment>=14 and @P_PDate<=A.DueDate_14 Then A.DueDate_14
		When A.Installment>=15 and @P_PDate<=A.DueDate_15 Then A.DueDate_15
		When A.Installment>=16 and @P_PDate<=A.DueDate_16 Then A.DueDate_16
		When A.Installment>=17 and @P_PDate<=A.DueDate_17 Then A.DueDate_17
		When A.Installment>=18 and @P_PDate<=A.DueDate_18 Then A.DueDate_18
		When A.Installment>=19 and @P_PDate<=A.DueDate_19 Then A.DueDate_19
		When A.Installment>=20 and @P_PDate<=A.DueDate_20 Then A.DueDate_20
		When A.Installment>=21 and @P_PDate<=A.DueDate_21 Then A.DueDate_21
		When A.Installment>=22 and @P_PDate<=A.DueDate_22 Then A.DueDate_22
		When A.Installment>=23 and @P_PDate<=A.DueDate_23 Then A.DueDate_23
		When A.Installment>=24 and @P_PDate<=A.DueDate_24 Then A.DueDate_24
		else A.BillDate
		end) as NextDueDate, 
	 sum(
	 Case 
		When A.Installment=0 Then A.Amount
		When A.Installment>=1 and @P_PDate<=A.DueDate_1 Then A.AmountDue_1 
		When A.Installment>=2 and @P_PDate<=A.DueDate_2 Then A.AmountDue_1+A.AmountDue_2 
		When A.Installment>=3 and @P_PDate<=A.DueDate_3 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3 
		When A.Installment>=4 and @P_PDate<=A.DueDate_4 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4 
		When A.Installment>=5 and @P_PDate<=A.DueDate_5 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5 
		When A.Installment>=6 and @P_PDate<=A.DueDate_6 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6 
		When A.Installment>=7 and @P_PDate<=A.DueDate_7 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7 
		When A.Installment>=8 and @P_PDate<=A.DueDate_8 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8 
		When A.Installment>=9 and @P_PDate<=A.DueDate_9 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9 
		When A.Installment>=10 and @P_PDate<=A.DueDate_10 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10 
		When A.Installment>=11 and @P_PDate<=A.DueDate_11 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11 
		When A.Installment>=12 and @P_PDate<=A.DueDate_12 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12 
		When A.Installment>=13 and @P_PDate<=A.DueDate_13 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13 
		When A.Installment>=14 and @P_PDate<=A.DueDate_14 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14
		When A.Installment>=15 and @P_PDate<=A.DueDate_15 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15 
		When A.Installment>=16 and @P_PDate<=A.DueDate_16 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16 
		When A.Installment>=17 and @P_PDate<=A.DueDate_17 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17 
		When A.Installment>=18 and @P_PDate<=A.DueDate_18 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18 
		When A.Installment>=19 and @P_PDate<=A.DueDate_19 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19 
		When A.Installment>=20 and @P_PDate<=A.DueDate_20 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19+A.AmountDue_20 
		When A.Installment>=21 and @P_PDate<=A.DueDate_21 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19+A.AmountDue_20+A.AmountDue_21 
		When A.Installment>=22 and @P_PDate<=A.DueDate_22 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19+A.AmountDue_20+A.AmountDue_21+A.AmountDue_22 
		When A.Installment>=23 and @P_PDate<=A.DueDate_23 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19+A.AmountDue_20+A.AmountDue_21+A.AmountDue_22+A.AmountDue_23 
		When A.Installment>=24 and @P_PDate<=A.DueDate_24 Then A.AmountDue_1+A.AmountDue_2+A.AmountDue_3+A.AmountDue_4+A.AmountDue_5+A.AmountDue_6+A.AmountDue_7+A.AmountDue_8+A.AmountDue_9+A.AmountDue_10+A.AmountDue_11+A.AmountDue_12+A.AmountDue_13+A.AmountDue_14+A.AmountDue_15+A.AmountDue_16+A.AmountDue_17+A.AmountDue_18+A.AmountDue_19+A.AmountDue_20+A.AmountDue_21+A.AmountDue_22+A.AmountDue_23+A.AmountDue_24 
		else A.Amount
		end *(V.Nominal_CC-V.Diff_CC-V.Payment_CC)/(V.Nominal_CC-V.Diff_CC)) as Nominal, 
	 'Policy No. ' + A.A_PolicyNo as Description
	 from Admlink A, Profile, nVoucher V
	 Where Profile.ID=A.ID and A.RefType='VIRTUAL' and A.Bank=@Bank and A.AccountNo=@P_AccountNo and V.Voucher=A.Voucher
	 Group by Profile.Name, A.A_PolicyNo







