CREATE function FL_UserTopro(@P_USERID varchar(50), @P_TOPRO varchar(10),@P_TOC varchar(10),@P_SEGMENT varchar(10),@P_PHOLDER varchar(10),@P_Insured varchar(10))    
RETURNS Table      
AS RETURN      
(    
SELECT Distinct TOPRO.TOPRO, TOPRO.Description, TOPRO.TOC, TOPRO.Expiry, TOPRO.CustomizableF, TOPRO.IncludeExtCoverF
--, TOP_PHolder.ID  as PHOLDER,   TOP_Insured.ID as Insured
from TOPRO 
Left Join TOP_Segment on (TOP_Segment.TOPRO=TOPRO.TOPRO)     
Left Join TOP_PHolder on (TOP_PHolder.TOPRO=TOPRO.TOPRO)  
Left Join TOP_Insured on (TOP_Insured.TOPRO=TOPRO.TOPRO)        
Where (TOPRO.TOPRO Like @P_TOPRO+'%' or TOPRO.Description like  @P_TOPRO+'%')
and TOPRO.TOC=Substring(@P_TOC, 1, len(TOPRO.TOC))
and TOPRO.AllowedF=1           
and (TOPRO.SegmentF=0 or TOP_Segment.Segment like @P_SEGMENT)   
and (TOPRO.PholderF=0 or TOP_PHolder.ID like @P_PHOLDER)   
and (TOPRO.InsuredF=0 or TOP_Insured.ID like @P_Insured) 
)
