BEGIN
DROP Procedure AutoClaimPayment_Process
END
GO
CREATE Procedure AutoClaimPayment_Process(@P_PDate as smalldatetime)                                                
as                                       
Select 
A.OANO,
A.SDate,
A.EDate,
'' as ClaimNo,
@P_PDate as PDate,
A.PolicyNo, 
A.CERTIFICATENO,
'' as Conj_PolicyNo,
'' as Conj_CertificateNo,
A.RefNo,
A.TOC,
A.Branch,
A.RefNo as ClaimRefNo,
Cp.NPayDate as RefDate,
'' as RefTime,
Cp.nPayDate as LossDate,
'' as LossTime,
A.RefNo as LossRefNo,
Cp.COL as CauseOfLoss,
'' as LossLocation,
'' as LossPlace,
'' as LossDescription,
0 as BackdatedF,
-1 as EventNo,
'' as EventName, 
C.PHolder as Claimant,
PHolder.Name as ClaimantInfo,
Cp.Payment as PaymentID,
'' as PaymentName,
'' as SurveyorID,
'' as SurveyorName,
'' as AssessorID,
'' as AssessorName,
Cp.Payment as LPaymentID,
'' as ClaimType,
Cp.NOC as NatureOfLoss,
Cp.TOI as InterestInsured,
Cp.Currency as Currency,
1 as LossItemAmount,
'INS.BENEFIT' as LossItem_1,
'INS.BENEFIT' as LossCategory_1,
'INS.BENEFIT' as LossItemDescription_1,
Cp.Amount*Case When Cp.PCTLOSS=0 Then 100 else Cp.PCTLOSS end/100 as EstimateClaim_1,
Cp.Amount*Case When Cp.PCTLOSS=0 Then 100 else Cp.PCTLOSS end/100 as IndemnityClaim_1
from ClaimPaymentSchedule Cp, Acceptance A, FN_POLICY_ONRISK(@P_PDate) as F, Cover C, Profile PHolder, TOC
Where A.ANO=F.ANO and C.CNO=A.CNO and PHolder.ID=C.PHolder
and TOC.TOC=A.TOC and TOC.AutoClaimPaymentF=1
and Cp.ANO=A.OANO and Cp.HoldF=0 
and Cp.Paydate<@P_PDate and Cp.NPayDate>=@P_PDate








