--polis info credit lmit dan policy limit
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PI19') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
DROP procedure PI19
END
GO
CREATE procedure PI19 (@P_ANO as integer)                
as                
Begin                
	Declare @PDate as smalldatetime
	Select @PDate=cast(year(getdate()) as varchar(4))+'/'+right('0'+cast(Month(getdate()) as varchar(4)),2)+'/'+right('0'+cast(Day(getdate()) as varchar(4)),2)

	Select 
	Max(ICoverPol.Amount) as Limit, 
	sum(coalesce(I.Amount,0)*coalesce(P.InstSIPCT,100)/100) as TotalLiability,
	Max(ICoverPol.Amount)-sum(coalesce(I.Amount,0)*coalesce(P.InstSIPCT,100)/100) as Remaining
	from Acceptance lA
	Inner Join Acceptance mA on (mA.OANO=lA.OANO)
	Left Join Acceptance A on (A.LANO=mA.ANO and A.ANO<>A.LANO and A.AType in ('N','E')  and A.AStatus='I')
	Left Join Payor_Schedule P on (P.ANO=A.ANO and P.InstDate<=@PDate and (P.InstLDate>@PDate or (P.InstLDate=@PDate and P.InstLDate=A.EDate)))
	Left Join GenDtab G on (G.FLDID=A.FLDID and G.VALUEID=A.VALUEID)
	Inner Join ICoverPol on (ICoverPol.ANO=lA.ANO and ICoverPol.Amount<>0)
	Left Join ICover I on (I.ANO=A.ANO and I.Currency=ICoverPol.Currency)
	Where lA.ANO=@P_ANO and lA.ANO=lA.LANO 
end   

GO
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PI20') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
DROP procedure PI20
END
GO
CREATE procedure PI20 (@P_ANO as integer)                
as                
Begin                
	Declare @PDate as smalldatetime
	Select @PDate=cast(year(getdate()) as varchar(4))+'/'+right('0'+cast(Month(getdate()) as varchar(4)),2)+'/'+right('0'+cast(Day(getdate()) as varchar(4)),2)

	Select 
	A.ValueID,
	coalesce(G.Description,A.ValueID) as Description,
	Max(AinfoDet.Limit) as Limit, 
	sum(coalesce(I.Amount,0)*coalesce(P.InstSIPCT,100)/100) as TotalLiability,
	Max(AinfoDet.Limit)-sum(coalesce(I.Amount,0)*coalesce(P.InstSIPCT,100)/100) as Remaining
	from Acceptance lA
	Inner Join Acceptance mA on (mA.OANO=lA.OANO)
	Left Join Acceptance A on (A.LANO=mA.ANO and A.ANO<>A.LANO and A.AType in ('N','E')  and A.AStatus='I')
	Left Join Payor_Schedule P on (P.ANO=A.ANO and P.InstDate<=@PDate and (P.InstLDate>@PDate or (P.InstLDate=@PDate and P.InstLDate=A.EDate)))
	Left Join GenDtab G on (G.FLDID=A.FLDID and G.VALUEID=A.VALUEID)
	Inner Join AInfoDet on (AInfoDet.ANO=lA.ANO and AInfoDet.Limit<>0 and AInfoDet.FLDID=A.FLDID and (AINFODet.ValueID='<All>' or AINFODET.VALUEID=A.VALUEID))
	Left Join ICover I on (I.ANO=A.ANO and I.Currency=AInfoDet.Currency)
	Where lA.ANO=@P_ANO and lA.ANO=lA.LANO 
	Group By A.ValueID, coalesce(G.Description,A.ValueID)
end   

GO
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PI21') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
DROP procedure PI21
END
GO
CREATE procedure PI21 (@P_ANO as integer)                
as                
Begin                
Select LANO, ANO, OANO, CertificateNo, ValueDesc, AName, SDate, EDate, TotalLimit, SUM (TotalLimit) OVER (PARTITION BY LANO) AS Balance
	from
	(
	Select 
		la.LANO, lA.ANO, lA.OANO, lA.CertificateNo, 'BB' as ValueID, 'Beginning Balance' as ValueDesc,'' as AName, lA.SDate, lA.EDate, I1.SI as TotalLimit
		from Acceptance lA
		Inner Join Cover C on (C.CNO=lA.CNO and C.OpenFlag=1)
		Inner Join ICover I1 on (I1.ANO=lA.ANO and I1.Category='M' and I1.SI<>0)
		Where lA.ANO=@P_ANO and lA.ANO=lA.LANO 

	Union All 

	Select 
		la.LANO, A.ANO, A.OANO, A.CertificateNo, A.ValueID, A.ValueDesc, A.AName, A.SDate, A.EDate, -I2.SI as TotalLimit
		from Acceptance lA
		Inner Join Cover C on (C.CNO=lA.CNO and C.OpenFlag=1)
		Inner Join ICover I1 on (I1.ANO=lA.ANO and I1.Category='M' and I1.SI<>0)
		Inner Join Acceptance A on (A.LANO=lA.ANO and A.ANO<>A.LANO and A.AType in ('N','E')  and A.AStatus='I')
		Inner Join ICover I2 on (I2.ANO=A.ANO and I2.TOI=I1.TOI and I2.Currency=I1.Currency)
		Where lA.ANO=@P_ANO and lA.ANO=lA.LANO 
	) S

	Order by LANO, ANO
end   

go

