 GENHTAB.FLDID9, GENHTAB.FLDTAG9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9, GENHTAB_9.FLDLOWER as FLDLOWER9, GENHTAB_9.FLDUPPER as FLDUPPER9, GENHTAB_9.FLDREGEX as FLDREGEX9,
