 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON GENHTAB.FLDID9 = GENHTAB_9.FLDID  
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON GENHTAB.FLDID10 = GENHTAB_10.FLDID  
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON GENHTAB.FLDID11 = GENHTAB_11.FLDID  
 LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON GENHTAB.FLDID12 = GENHTAB_12.FLDID  
