 LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON GENHTAB.FLDID14 = GENHTAB_14.FLDID  
 LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON GENHTAB.FLDID15 = GENHTAB_15.FLDID  
WHERE GENHTAB.FLDID = @P_FLDID  




